#include <bits/stdc++.h>
using namespace std;using U=uint32_t;int pc(U x){return __builtin_popcount(x);}int lo(U x){return __builtin_ctz(x);}
struct G{int n;array<U,32>a{};G(int n):n(n){};void add(int i,int j){assert(i!=j&&!(a[i]>>j&1));a[i]|=1u<<j;a[j]|=1u<<i;}void del(int i,int j){a[i]^=1u<<j;a[j]^=1u<<i;}vector<pair<int,int>>edges()const{vector<pair<int,int>>e;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(a[i]>>j&1)e.emplace_back(i,j);return e;}};
using P=vector<U>;
void ref(const G&g,P&p){while(1){P q;for(U m:p){if(pc(m)==1){q.push_back(m);continue;}map<uint64_t,U>grp;for(U t=m;t;t&=t-1){uint64_t k=0;for(U c:p)k=k*4+pc(g.a[lo(t)]&c);grp[k]|=t&-t;}for(auto[k,z]:grp)q.push_back(z);}if(q.size()==p.size())return;p=move(q);}}
string g6(const G&g,P p){string s(1,char(g.n+63));int b=0,t=0;for(int j=1;j<g.n;j++)for(int i=0;i<j;i++){b=2*b+bool(g.a[lo(p[j])]&p[i]);if(++t==6){s+=char(b+63);b=t=0;}}if(t)s+=char((b<<(6-t))+63);return s;}
void cr(const G&g,P p,string&best){ref(g,p);if((int)p.size()==g.n){auto s=g6(g,p);if(best.empty()||s<best)best=s;return;}int k=-1,mn=99;for(int i=0;i<(int)p.size();i++)if(pc(p[i])>1&&pc(p[i])<mn)mn=pc(p[k=i]);for(U m=p[k];m;m&=m-1){U v=m&-m;P q=p;q[k]^=v;q.insert(q.begin()+k,v);cr(g,q,best);}}
string canon(const G&g){string s;cr(g,{(1u<<g.n)-1},s);return s;}G parse(string s){G g(s[0]-63);int b=0;for(int j=1;j<g.n;j++)for(int i=0;i<j;i++,b++)if((s[1+b/6]-63)>>(5-b%6)&1)g.add(i,j);return g;}
// Exhaustive palette search, with color-label symmetry and partial constraints.
struct S{const G&g;int k;array<int,32>c{},w{};vector<array<int,3>>nb;S(const G&g,int k):g(g),k(k){c.fill(-1);for(int i=0;i<g.n;i++){array<int,3>t;U m=g.a[i];for(int&v:t){v=lo(m);m&=m-1;}nb.push_back(t);}}
 bool local(int v){U m=0;int unset=0;for(int u:nb[v]){if(c[u]<0)unset++;else{if(c[u]==c[v])return false;m|=1u<<c[u];}}return pc(m)<=2&&pc(m)+unset>=2;}
 bool dfs(int left,int used){if(!left){w=c;return true;}int v=-1,best=-1;for(int i=0;i<g.n;i++)if(c[i]<0){int score=0;for(int j:nb[i]){score+=4*(c[j]>=0);for(int h:nb[j])score+=(c[h]>=0);}if(score>best)best=score,v=i;}for(int x=0;x<min(k,used+1);x++){c[v]=x;bool ok=local(v);for(int u:nb[v])ok&=local(u);if(ok&&dfs(left-1,max(used,x+1)))return true;c[v]=-1;}return false;}
 bool solve(){return dfs(g.n,0);}};
// Independent unbounded equality-pattern solver.
struct UF{array<int,32>p;UF(){iota(p.begin(),p.end(),0);}int r(int v)const{while(p[v]!=v)v=p[v];return v;}void join(int a,int b){p[r(a)]=r(b);}};
struct T{const G&g;vector<array<int,3>>nb;array<int,32>w{};T(const G&g):g(g){for(int i=0;i<g.n;i++){array<int,3>t;U m=g.a[i];for(int&v:t){v=lo(m);m&=m-1;}nb.push_back(t);}}bool valid(const UF&f,const vector<pair<int,int>>&neq){for(auto[a,b]:neq)if(f.r(a)==f.r(b))return false;return true;}
 bool dfs(UF f,vector<pair<int,int>>neq,U rem){if(!rem){for(int i=0;i<g.n;i++)w[i]=f.r(i);return true;}int v=-1;U opt=0;for(U m=rem;m;m&=m-1){int i=lo(m);U o=0;for(int j=0;j<3;j++){int a=nb[i][(j+1)%3],b=nb[i][(j+2)%3],c=nb[i][j];UF h=f;h.join(a,b);if(h.r(a)!=h.r(c)&&valid(h,neq))o|=1u<<j;}if(!o)return false;if(v<0||pc(o)<pc(opt)){v=i;opt=o;if(pc(o)==1)break;}}for(U m=opt;m;m&=m-1){int j=lo(m),a=nb[v][(j+1)%3],b=nb[v][(j+2)%3],c=nb[v][j];UF h=f;h.join(a,b);auto nn=neq;nn.emplace_back(a,c);if(dfs(h,nn,rem^(1u<<v)))return true;}return false;}
 bool solve(){return dfs(UF(),g.edges(),(1u<<g.n)-1);}};
bool valid(const G&g,const array<int,32>&w){for(int i=0;i<g.n;i++){U s=0;for(U m=g.a[i];m;m&=m-1){int j=lo(m);if(w[i]==w[j])return false;s|=1u<<w[j];}if(pc(s)!=2)return false;}return true;}
void check(const set<string>&ss,int n){array<int,5>c{};ofstream f("exceptions_"+to_string(n)+".txt");for(auto&s:ss){G g=parse(s);c[0]++;S a(g,3),b(g,4);if(a.solve()){assert(valid(g,a.w));c[1]++;}else if(b.solve()){assert(valid(g,b.w));c[2]++;}else{T p(g);if(p.solve()){assert(valid(g,p.w));c[3]++;f<<"counterexample "<<s;for(int i=0;i<n;i++)f<<' '<<p.w[i];f<<endl;}else{c[4]++;f<<"impossible "<<s<<endl;}}}cout<<n;for(int x:c)cout<<','<<x;cout<<endl;}
int main(int argc,char**argv){int mx=argc>1?atoi(argv[1]):16;vector<set<string>>all(mx+1);G k(4);for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)k.add(i,j);all[4].insert(canon(k));cout<<"n,total,3,4,5plus,impossible"<<endl;check(all[4],4);for(int n=6;n<=mx;n+=2){auto&ss=all[n];auto emit=[&](const G&g){for(int i=0;i<n;i++)assert(pc(g.a[i])==3);ss.insert(canon(g));};for(auto&s:all[n-2]){G g=parse(s);auto e=g.edges();for(int i=0;i<(int)e.size();i++)for(int j=i+1;j<(int)e.size();j++){auto[a,b]=e[i];auto[c,d]=e[j];G h=g;h.n=n;h.del(a,b);h.del(c,d);h.add(a,n-2);h.add(b,n-2);h.add(c,n-1);h.add(d,n-1);h.add(n-2,n-1);emit(h);}}
 if(n>=8)for(auto&s:all[n-4]){G g=parse(s);for(auto[a,b]:g.edges()){G h=g;h.n=n;h.del(a,b);int x=n-4,y=n-3,u=n-2,v=n-1;h.add(a,x);h.add(b,y);h.add(x,u);h.add(x,v);h.add(y,u);h.add(y,v);h.add(u,v);emit(h);}}
 for(int a=4;a<=n-2-a;a+=2){int b=n-2-a;for(auto&s:all[a])for(auto&t:all[b]){G g=parse(s),h=parse(t);for(auto[i,j]:g.edges())for(auto[k,l]:h.edges()){G z(n);for(auto[u,v]:g.edges())z.add(u,v);for(auto[u,v]:h.edges())z.add(u+a,v+a);z.del(i,j);z.del(k+a,l+a);z.add(i,n-2);z.add(j,n-2);z.add(k+a,n-1);z.add(l+a,n-1);z.add(n-2,n-1);emit(z);}}}
 if(n>=10)for(auto&s:all[n-6]){G g=parse(s);for(auto[a,b]:g.edges()){G h=g;h.n=n;h.del(a,b);int x=n-6,y=n-5,p=n-4,q=n-3,u=n-2,v=n-1;h.add(a,x);h.add(b,y);h.add(x,y);h.add(x,p);h.add(y,q);h.add(p,u);h.add(p,v);h.add(q,u);h.add(q,v);h.add(u,v);emit(h);}}
 cerr<<"Generated "<<n<<" count "<<ss.size()<<endl;ofstream f("graphs_"+to_string(n)+".g6");for(auto&s:ss)f<<s<<'\n';check(ss,n);}}
